def rebalance(questions):
    for i, q in enumerate(questions):
        target = i % 4
        a = q["ans"]
        if a != target:
            q["opts"][a], q["opts"][target] = q["opts"][target], q["opts"][a]
            q["ans"] = target
    return questions


def _validate(name, lessons, questions, want_ch):
    problems = []
    if len(lessons) != want_ch:
        problems.append(f"  {name}: {len(lessons)} lessons (want {want_ch})")
    short = [f"{l['title'][:40]} ({len(l['html'])})" for l in lessons if len(l["html"]) < 2500]
    if short:
        problems.append(f"  {name} below depth: {short}")
    if len(questions) != 35:
        problems.append(f"  {name}: {len(questions)} questions (want 35)")
    for q in questions:
        if len(q["opts"]) != 4 or not (0 <= q["ans"] <= 3):
            problems.append(f"  {name} malformed '{q['q'][:40]}'")
    import re as _re
    blob = json.dumps({"l": lessons, "q": questions}, ensure_ascii=False)
    if "ERPNext" in blob:
        problems.append(f"  {name}: ERPNext branding leakage")
    if _re.search(r"\b[Ll]aws?\b", blob):
        problems.append(f"  {name}: 'law' register leakage")
    low = blob.lower()
    for marker in ["certified professional", "the consultant", "consultants", "the academy",
                   "this academy", "engagement", "constitution", "costume", "scar tissue",
                   "witness", "testimony"] + EDITORIAL_BAN:
        if marker in low:
            problems.append(f"  {name}: banned phrase '{marker}'")
    return problems


def main():
    root = os.getcwd()
    with io.open(os.path.join(root, INIT), encoding="utf-8") as f:
        init = f.read()
    with io.open(os.path.join(root, DATA_PATH), encoding="utf-8") as f:
        data = json.load(f)

    if '"3.196.0"' in init:
        print("Already applied. Nothing to do.")
        return
    if '"3.195.0"' not in init:
        sys.exit("ABORT: not at v3.195.0.")
    if "items_costs" not in data:
        sys.exit("ABORT: items_costs module not found in data file.")

    problems = _validate("PROC2", LESSONS_P2, QUESTIONS_P2, 9)
    if problems:
        print("ABORT — not clean:")
        print("\n".join(problems))
        sys.exit(1)

    bank = rebalance(list(QUESTIONS_P2))
    dist = {c: sum(1 for q in bank if q["ans"] == i) for i, c in enumerate("ABCD")}
    if max(dist.values()) > 10:
        print(f"ABORT — PROC2 spread failed: {dist}")
        sys.exit(1)
    total = sum(len(l["html"]) for l in LESSONS_P2)
    print(f"PROC 2 v3: {len(LESSONS_P2)} chapters ({total:,} chars, min {min(len(l['html']) for l in LESSONS_P2):,}), bank {len(bank)}, spread {dist}")

    if CHECK_ONLY:
        print("--check given; no files written.")
        return

    data["items_costs"]["lessons"] = LESSONS_P2
    data["items_costs"]["questions"] = bank
    data["items_costs"]["desc"] = ("Purchase items, units, costs, and planning in ZhiftERP: the buying section on the one register record with Is Purchase Item and the one-record principle; purchase units with physically verified factors, the rate-and-unit pairing rule, and governed pack-size changes; buying price lists with sourced rates and the changes and completeness reads; the three figures called cost — quoted, invoiced, and landed — with their sources, uses, and the margin vocabulary rule; the planning fields — measured lead times, costed safety stock, reorder parameters, and supplier constraints; reading the last purchase rate within its boundaries and the monthly price trend read with the selling-review hand-off; and landed-cost thinking — the consignment worksheet, the landed comparison rule, container arithmetic, and the worksheet-versus-actual reconciliation.")

    with io.open(os.path.join(root, DATA_PATH), "w", encoding="utf-8") as f:
        json.dump(data, f, indent=1, ensure_ascii=False)
        f.write("\n")
    with io.open(os.path.join(root, INIT), "w", encoding="utf-8") as f:
        f.write(init.replace('"3.195.0"', '"3.196.0"'))
    print("  data: PROCUREMENT 2 lessons + bank REPLACED (style v3, textbook manual register)")
    print("wrote __version__ -> 3.196.0")


if __name__ == "__main__":
    main()
